// Le domande "quanti anni fa" calcolano la risposta sull'anno corrente
(function(){
 var Y=new Date().getFullYear();
 [QUANTO_VALE_DATA,QUANTO_VALE_DATA_EN,QUANTO_VALE_DATA_ES].forEach(function(arr){
  arr.forEach(function(x){
   if(typeof x.y==="number"){x.risposta=Y-x.y;}
   if(x.risposta>x.max){x.max=Math.ceil(x.risposta*1.25/10)*10;}
   if(x.risposta<x.min){x.min=0;}
  });
 });
})();
function qvData(){
 return (typeof LANG!=="undefined"&&LANG==="en")?QUANTO_VALE_DATA_EN:(typeof LANG!=="undefined"&&LANG==="es")?QUANTO_VALE_DATA_ES:QUANTO_VALE_DATA;
}
